Verdict: bug found

Line 25: `if(queued==0) ck(pthread_cond_wait(&cv,&m));`

if checks once, so an allowed spurious return reaches the removal step on an empty mailbox.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 | read queued -> 0 under m |  | queue empty |
| 2 | cond_wait releases m and waits |  | B not yet scheduled |
| 3 | wait returns spuriously and reacquires m |  | queued still 0 |
| 4 | --queued |  | invalid consumption without predicate recheck |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -22,7 +22,7 @@
 static int queued;
 static void *a(void *p) {
     (void)p; ck(pthread_mutex_lock(&m));
-    if(queued==0) ck(pthread_cond_wait(&cv,&m));
+    while(queued==0) ck(pthread_cond_wait(&cv,&m));
     --queued; assert(queued>=0); ck(pthread_mutex_unlock(&m)); return NULL;
 }
 static void *b(void *p) {
```

while rechecks the durable queued count with m held. The removal occurs only after a real item exists.

Verdict: bug found

Line 30: `ck(pthread_mutex_destroy(&job->m)); free(job);`

The job’s storage and embedded mutex are released before the worker finishes. That combines an invalid mutex lifecycle with a possible later use-after-free.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 | worker owns job mutex |  | job is live and in use |
| 2 | V(acquired) |  | main may proceed |
| 3 |  | destroy job mutex | invalid destruction of owned object |
| 4 |  | free(job) | worker still holds a pointer into freed storage |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -27,7 +27,7 @@
 int main(void) {
     pthread_t t; job=malloc(sizeof *job); assert(job); job->value=3; ck(pthread_mutex_init(&job->m,NULL));
     SO(sem_init(&acquired,0,0)); SO(sem_init(&finish,0,0)); ck(pthread_create(&t,NULL,worker,NULL)); P(acquired);
+    V(finish); ck(pthread_join(t,NULL));
     ck(pthread_mutex_destroy(&job->m)); free(job);
-    V(finish); ck(pthread_join(t,NULL));
     SO(sem_destroy(&acquired)); SO(sem_destroy(&finish)); return 0;
 }
```

Keep the entire job alive through the finish handshake and join. Only after the worker’s final unlock can main destroy the embedded mutex and free its enclosing allocation.

Plan: Separate the partial-completion predicate from full lifecycle completion.

```c
#include <pthread.h>
#include <assert.h>
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv=PTHREAD_COND_INITIALIZER;
static int ids[4],done[4],finished;
static void *worker(void *p) {
    int id=*(int *)p; assert((pthread_mutex_lock(&m)) == 0); done[id]=1; ++finished;
    assert((pthread_cond_broadcast(&cv)) == 0); assert((pthread_mutex_unlock(&m)) == 0); return NULL;
}
int main(void) {
    pthread_t t[4];
    for(int i=0;i<4;i++) { ids[i]=i; assert((pthread_create(&t[i],NULL,worker,&ids[i])) == 0); }
    assert((pthread_mutex_lock(&m)) == 0);
    while(finished<2) assert((pthread_cond_wait(&cv,&m)) == 0);
    int snapshot=0; for(int i=0;i<4;i++) snapshot+=done[i]; assert(snapshot>=2);
    assert((pthread_mutex_unlock(&m)) == 0);
    for(int i=0;i<4;i++) assert((pthread_join(t[i],NULL)) == 0);
    assert(finished==4); assert((pthread_cond_destroy(&cv)) == 0); assert((pthread_mutex_destroy(&m)) == 0); return 0;
}
```

Why it is correct: Main reads the mid-run snapshot under m, so it cannot race with remaining updates. The durable finished count tolerates notifications before waiting. Reaching quorum does not authorize destruction; all four joins establish that no user remains.

