#include <pthread.h>
#include <stdlib.h>
#include <assert.h>
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t arrivals=PTHREAD_COND_INITIALIZER,done=PTHREAD_COND_INITIALIZER;
