static void *customer(void *p) {
    int id=*(int *)p; assert((pthread_mutex_lock(&m)) == 0);
    if(count==2) { ++rejected; assert((pthread_mutex_unlock(&m)) == 0); return NULL; }
    q[tail]=id; tail=(tail+1)%2; ++count; ++accepted;
    assert((pthread_cond_signal(&arrivals)) == 0);
    while(!served[id]) assert((pthread_cond_wait(&done,&m)) == 0);
    assert((pthread_mutex_unlock(&m)) == 0); return NULL;
}
static void *barber(void *p) {
    (void)p;
    for(int jobs=0;jobs<=5;jobs++) {
        assert((pthread_mutex_lock(&m)) == 0);
        while(count==0 && !closed) assert((pthread_cond_wait(&arrivals,&m)) == 0);
        if(count==0) { assert((pthread_mutex_unlock(&m)) == 0); return NULL; }
        int id=q[head]; head=(head+1)%2; --count; served[id]=1;
