Plan: Allocate unique job indexes atomically and let each owner write its own slot.

```c
#include <pthread.h>
#include <stdio.h>
#include <assert.h>
#include <stdatomic.h>
static atomic_int next_job;
static int result[8];
static void *worker(void *p) {
    (void)p;
    for(int tries=0;tries<8;tries++) {
        int job=atomic_fetch_add_explicit(&next_job,1,memory_order_relaxed);
        if(job>=8) break;
        result[job]=(job+1)*(job+1);
    } return NULL;
}
int main(void) {
    pthread_t t[3]; atomic_init(&next_job,0);
    for(int i=0;i<3;i++) assert((pthread_create(&t[i],NULL,worker,NULL)) == 0);
    for(int i=0;i<3;i++) assert((pthread_join(t[i],NULL)) == 0);
    for(int i=0;i<8;i++) assert(result[i]==(i+1)*(i+1));
    puts("each independent job has one owner"); return 0;
}
```

Why it is correct: fetch-add assigns each real job to exactly one worker, so result writes do not conflict. Relaxed ordering suffices for index uniqueness because the input is initialized before creation and joins order final result reads. No blocking dependency can form a deadlock.

