typedef struct Node { int key; pthread_mutex_t m; struct Node *next; } Node;
static Node tail={INT_MAX,PTHREAD_MUTEX_INITIALIZER,NULL};
static Node head={INT_MIN,PTHREAD_MUTEX_INITIALIZER,&tail};
