    while(curr->key<n->key) {
        assert((pthread_mutex_unlock(&prev->m)) == 0); prev=curr;
        curr=prev->next; assert((pthread_mutex_lock(&curr->m)) == 0);
    }
    n->next=curr; prev->next=n;
    assert((pthread_mutex_unlock(&curr->m)) == 0); assert((pthread_mutex_unlock(&prev->m)) == 0); return NULL;
}
