        assert(sem_wait(&(filtered_empty)) == 0); filtered=local*local; assert(sem_post(&(filtered_full)) == 0);
    } return NULL;
}
static void *collect(void *p) {
    (void)p; for(int i=0;i<4;i++) { assert(sem_wait(&(filtered_full)) == 0); total+=filtered; assert(sem_post(&(filtered_empty)) == 0); } return NULL;
}
